check "bash scripts parse before shell startup" "bash -n bootstrap.sh home/.bash_profile home/.bashrc home/bash/*.sh home/bin/proxy-env installer/*.sh tests/*.sh tests/validate/*.sh"
check "removed Codex wrapper has no stale artifacts" "! test -e home/bin/codex && ! test -e tests/test-codex-wrapper.sh"
check "Bash login shells delegate to the managed bashrc" "grep -Fq 'source \"\$HOME/.bashrc\"' home/.bash_profile"
check "managed bashrc loads deployed Bash modules" "grep -Fq '\$HOME/bash/.path' home/.bashrc && grep -Fq '\$HOME/bash/.aliases' home/.bashrc && cache_dir=\$(mktemp -d) && HOME=\"\$PWD/home\" XDG_CACHE_HOME=\"\$cache_dir/cache\" XDG_DATA_HOME=\"\$cache_dir/data\" XDG_STATE_HOME=\"\$cache_dir/state\" bash --noprofile --rcfile home/.bashrc -ic 'declare -F proxy'; status=\$?; rm -rf \"\$cache_dir\"; [[ \$status -eq 0 ]]"
check "installer deployment and result behavior" "test -x tests/test-install.sh && ./tests/test-install.sh"
check_if_available fish "fish scripts parse before shell startup" "for f in home/fish/*.fish; do fish -n \"\$f\" || exit 1; done"
check "snippet tooling uses the corrected name" "test -x home/bin/snippet && ! test -e home/bin/snippte && test -f home/bash/snippet.sh && ! test -e home/bash/snippte.sh && test -f home/fish/snippet.fish && ! test -e home/fish/snippte.fish && ! grep -rn 'snippte' home/.bashrc home/.tmux.conf home/bash home/fish home/bin home/.config/herdr"
check "Fish FZF bindings are independent of the package manager" "grep -Fq 'fzf --fish | source' home/fish/fish_fzf_bindings.fish && ! grep -Fq '/opt/homebrew' home/fish/fish_fzf_bindings.fish"
check_if_available fish "Fish starts without fzf" "fish_path=\$(command -v fish); env PATH=/nonexistent \"\$fish_path\" --no-config -c 'source home/fish/fish_fzf_bindings.fish; fish_user_key_bindings'"
check_if_available fish "fish login starts without optional-tool errors" "! fish -lc true 2>&1 | grep -Eq 'Unknown command: bass|Homebrew installation not found|npm not found'"
check "Linux Home Manager sessions use an English locale" "grep -Fq 'LANG = \"en_US.UTF-8\";' home/.config/home-manager/modules/platform/linux.nix && grep -Fq 'LANGUAGE = \"en_US:en\";' home/.config/home-manager/modules/platform/linux.nix && ! grep -Fq 'LC_ALL' home/.config/home-manager/modules/platform/linux.nix"
check_if_available fish "Fish uses English messages without overriding locale categories" "env LANG=zh_CN.UTF-8 LANGUAGE=zh_CN:en_US:en LC_ALL=C fish --no-config -c 'source home/fish/locale.fish; test \"\$LANG\" = en_US.UTF-8; and test \"\$LANGUAGE\" = en_US:en; and test \"\$LC_ALL\" = C'"
